const fs = require('node:fs'), path = require('node:path'), crypto = require('node:crypto'), assert = require('node:assert/strict');
(async () => {
  let lib;
  for (const entry of process.env.PATH.split(path.delimiter)) {
    const candidate = path.resolve(entry, '../firebase-tools/lib');
    if (fs.existsSync(path.join(candidate, 'requireAuth.js'))) { lib = candidate; break; }
  }
  assert.ok(lib, 'Run inside npm exec firebase-tools');
  const email = 'phuckk2101@gmail.com', project = 'bepxinh-b0be7';
  const options = {project, account:email, nonInteractive:true};
  const auth = require(path.join(lib, 'auth'));
  auth.setActiveAccount(options, auth.selectAccount(email, process.cwd()));
  assert.equal(options.user.email, email);
  await require(path.join(lib, 'requireAuth')).requireAuth(options);
  const {Client} = require(path.join(lib, 'apiv2'));
  const api = new Client({urlPrefix:'https://firebaserules.googleapis.com',auth:true});
  const release = (await api.get(`/v1/projects/${project}/releases/cloud.firestore`)).body;
  const ruleset = (await api.get(`/v1/${release.rulesetName}`)).body;
  const normalize = value => value.replace(/\r\n/g,'\n');
  const local = normalize(fs.readFileSync('firestore.rules','utf8'));
  const remote = normalize(ruleset.source.files.find(file => file.name === 'firestore.rules').content);
  assert.equal(remote, local, 'Live rules differ from reviewed source');
  console.log(JSON.stringify({ruleset:release.rulesetName,sha256:crypto.createHash('sha256').update(remote).digest('hex'),match:true}));
})().catch(error=>{console.error(error.message);process.exitCode=1;});
